@Entity(tableName = "posts", foreignKeys = [ForeignKey(
    entity = UserEntity::class, parentColumns = ["id"], childColumns = ["authorId"],
    onDelete = ForeignKey.CASCADE,
)], indices = [Index("authorId")])
data class PostEntity(
    @PrimaryKey val id: Long,
    val authorId: Long,
    val title: String,
)

data class UserWithPosts(
    @Embedded val user: UserEntity,
    @Relation(parentColumn = "id", entityColumn = "authorId")
    val posts: List<PostEntity>,
)

@Dao
interface UserDao {
    @Transaction
    @Query("SELECT * FROM users WHERE id = :id")
    suspend fun userWithPosts(id: Long): UserWithPosts?
}

val MIGRATION_1_2 = object : Migration(1, 2) {
    override fun migrate(db: SupportSQLiteDatabase) {
        db.execSQL("ALTER TABLE users ADD COLUMN avatarUrl TEXT")
    }
}

val MIGRATION_2_3 = object : Migration(2, 3) {
    override fun migrate(db: SupportSQLiteDatabase) {
        db.execSQL("""
            CREATE TABLE posts_new (
                id INTEGER PRIMARY KEY NOT NULL,
                authorId INTEGER NOT NULL,
                title TEXT NOT NULL,
                publishedAt INTEGER NOT NULL DEFAULT 0,
                FOREIGN KEY(authorId) REFERENCES users(id) ON DELETE CASCADE
            )
        """.trimIndent())
        db.execSQL("INSERT INTO posts_new (id, authorId, title) SELECT id, authorId, title FROM posts")
        db.execSQL("DROP TABLE posts")
        db.execSQL("ALTER TABLE posts_new RENAME TO posts")
    }
}

class MigrationTest {
    @get:Rule val helper = MigrationTestHelper(
        InstrumentationRegistry.getInstrumentation(),
        AppDatabase::class.java,
    )

    @Test fun migrate1To2() {
        helper.createDatabase(TEST_DB, 1).apply {
            execSQL("INSERT INTO users (id, name, email, createdAt) VALUES (1, \"Fer\", \"a@b\", 0)")
            close()
        }
        helper.runMigrationsAndValidate(TEST_DB, 2, true, MIGRATION_1_2).apply {
            val c = query("SELECT avatarUrl FROM users WHERE id = 1")
            c.moveToFirst()
            assert(c.isNull(0))
            close()
        }
    }
    companion object { const val TEST_DB = "migration-test" }
}
